#include <stdio.h>

static unsigned int state = 1;

void set_seed(unsigned int seed) {
    state = seed;
}

int next_random(void) {
    state = state * 1103515245u + 12345u;
    return (int)(state / 65536 % 32768);
}

int main(void) {
    unsigned int seed;
    int k;
    scanf("%u %d", &seed, &k);
    set_seed(seed);
    for (int i = 0; i < k; i++) {
        if (i > 0) {
            printf(" ");
        }
        printf("%d", next_random());
    }
    printf("\n");
    return 0;
}

